import java.io.*;
import java.util.*;
public class G {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        InputReader in = new InputReader(reader);
        TaskE solver = new TaskE();
        solver.solve(1, in, writer);
        writer.flush();
        writer.close();
    }
    static class TaskE {
        class MinCostMaxFlow {
            List<Edge>[] graph;
            Edge[][] edgesArr;
            int[] dist;
            int N, S, T, maxFlow, minCost;
            final int INF = Integer.MAX_VALUE / 100;
            int edgeIdx = 0;

            class Edge {
                int u, flow, rev, cost;
                Edge(int u, int flow, int cost, int rev) {
                    this.u = u; this.flow = flow; this.cost = cost; this.rev = rev;
                }
            }

            void addEdge(int u, int v, int flow, int cost) {
                int lu = graph[u].size(), lv = graph[v].size();
                graph[u].add(new Edge(v, flow, cost, lv));
                graph[v].add(new Edge(u, 0, -cost, lu));
            }

            void convertToArray() {
                edgesArr = new Edge[N][];
                for (int i = 0; i < N; i++) {
                    edgesArr[i] = new Edge[graph[i].size()];
                    for (int j = 0; j < graph[i].size(); j++) {
                        edgesArr[i][j] = graph[i].get(j);
                    }
                    graph[i].clear();
                }
            }

            MinCostMaxFlow(int n, int s, int t) {
                N = n; S = s; T = t;
                graph = new ArrayList[N];
                for (int i = 0; i < N; i++) {
                    graph[i] = new ArrayList<>();
                }
                dist = new int[N];
            }

            boolean bellmanFordCheck() {
                Arrays.fill(dist, INF);
                dist[S] = 0;
                for (int i = 0; i < N - 1; i++) {
                    for (int j = 0; j < N; j++) {
                        for (Edge e : edgesArr[j]) {
                            if (e.flow > 0 && dist[j] + e.cost < dist[e.u]) {
                                dist[e.u] = dist[j] + e.cost;
                            }
                        }
                    }
                }
                for (int j = 0; j < N; j++) {
                    for (Edge e : edgesArr[j]) {
                        if (e.flow > 0 && dist[j] + e.cost < dist[e.u]) return false;
                    }
                }
                return true;
            }

            int[] parent, parentEdge;
            int[] node;
            int[] visit;
            int[] prev, prevEdge;
            int[] distance;

            boolean spfa() {
                node = new int[N];
                visit = new int[N];
                parent = new int[N];
                parentEdge = new int[N];
                distance = new int[N];
                Arrays.fill(distance, INF);
                Queue<Integer> q = new LinkedList<>();
                distance[S] = 0;
                q.offer(S);
                while (!q.isEmpty()) {
                    int u = q.poll();
                    visit[u] = 2;
                    for (int i = 0; i < edgesArr[u].length; i++) {
                        Edge e = edgesArr[u][i];
                        if (e.flow > 0 && distance[u] + e.cost < distance[e.u]) {
                            distance[e.u] = distance[u] + e.cost;
                            parent[e.u] = u;
                            parentEdge[e.u] = i;
                            if (visit[e.u] == 0) {
                                q.offer(e.u);
                                visit[e.u] = 1;
                            }
                        }
                    }
                }
                return visit[T] != 0;
            }

            boolean dijkstra() {
                Arrays.fill(distance, INF);
                parent = new int[N];
                parentEdge = new int[N];
                Arrays.fill(parent, -1);
                PriorityQueue<Pair> pq = new PriorityQueue<>((a, b) -> Integer.compare(a.dist, b.dist));
                distance[S] = 0;
                pq.offer(new Pair(S, 0));
                while (!pq.isEmpty()) {
                    Pair p = pq.poll();
                    if (p.dist > distance[p.u]) continue;
                    for (int i = 0; i < edgesArr[p.u].length; i++) {
                        Edge e = edgesArr[p.u][i];
                        if (e.flow > 0 && distance[p.u] + e.cost < distance[e.u]) {
                            distance[e.u] = distance[p.u] + e.cost;
                            parent[e.u] = p.u;
                            parentEdge[e.u] = i;
                            pq.offer(new Pair(e.u, distance[e.u]));
                        }
                    }
                }
                return parent[T] != -1;
            }

            int augment() {
                int flow = Integer.MAX_VALUE;
                for (int p = T; p != S; p = parent[p]) {
                    int u = parent[p], i = parentEdge[p];
                    flow = Math.min(flow, edgesArr[u][i].flow);
                }
                for (int p = T; p != S; p = parent[p]) {
                    int u = parent[p], i = parentEdge[p];
                    edgesArr[u][i].flow -= flow;
                    int rev = edgesArr[u][i].rev;
                    edgesArr[p][rev].flow += flow;
                }
                maxFlow += flow;
                return flow;
            }

            boolean minCostFlow() {
                while (bellmanFordCheck()) {
                    minCost += dist[T] * augment();
                }
                return true;
            }

            class Pair {
                int u, dist;
                Pair(int u, int dist) {
                    this.u = u; this.dist = dist;
                }
            }
        }

        int n, m, k, c, d;
        int[] a, f;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt(); m = in.nextInt(); k = in.nextInt(); c = in.nextInt(); d = in.nextInt();
            int maxl = n + k;
            int T = n * maxl + 1;
            MinCostMaxFlow flow = new MinCostMaxFlow(T + 1, 0, T);
            a = new int[k + 1];
            f = new int[n + 1];
            for (int i = 1; i <= k; i++) {
                a[i] = in.nextInt();
                f[a[i]]++;
            }
            for (int i = 1; i <= n; i++) {
                if (f[i] == 0) continue;
                flow.addEdge(0, i, f[i], 0);
            }
            for (int i = 2; i <= n; i++) {
                for (int l = 0; l < maxl - 1; l++) {
                    flow.addEdge(l * n + i, (l + 1) * n + i, k, c);
                }
            }
            for (int i = 1; i <= m; i++) {
                int a = in.nextInt(), b = in.nextInt();
                for (int l = 0; l < maxl - 1; l++) {
                    for (int p = 1; p <= k; p++) {
                        if (a != 1)
                            flow.addEdge(n * l + a, n * (l + 1) + b, 1, d * (2 * p - 1) + c);
                        if (b != 1)
                            flow.addEdge(n * l + b, n * (l + 1) + a, 1, d * (2 * p - 1) + c);
                    }
                }
            }
            for (int l = 1; l < maxl; l++) {
                flow.addEdge(l * n + 1, T, k, 0);
            }
            flow.convertToArray();
            flow.minCostFlow();
            if (flow.maxFlow != k) {
                out.println("BUG");
            } else {
                out.println(flow.minCost);
            }
        }
    }

    static class InputReader {
        BufferedReader br;
        StringTokenizer st;
        public InputReader(BufferedReader br) {
            this.br = br;
            st = null;
        }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
